def parse_ini(text):
    """Sections, keys and values of INI text. See TASK.md."""
    sections = {}
    section = ""
    current_key = None

    for line_number, line in enumerate(text.split("\n"), 1):
        if line.endswith("\r"):
            line = line[:-1]

        stripped = line.strip()
        if not stripped or stripped.startswith((";", "#")):
            continue

        if line[:1] in " \t":
            if current_key is None:
                raise ValueError(f"invalid continuation at line {line_number}")
            sections[section][current_key] += "\n" + stripped
            continue

        if stripped.startswith("[") or stripped.endswith("]"):
            if not (stripped.startswith("[") and stripped.endswith("]")):
                raise ValueError(f"invalid section at line {line_number}")
            name = stripped[1:-1].strip()
            if not name:
                raise ValueError(f"empty section at line {line_number}")
            section = name
            sections.setdefault(section, {})
            current_key = None
            continue

        if "=" in line:
            raw_key, value = line.split("=", 1)
            key = raw_key.strip().lower()
            if not key:
                raise ValueError(f"empty key at line {line_number}")
            sections.setdefault(section, {})[key] = value.strip()
            current_key = key
            continue

        raise ValueError(f"invalid line at line {line_number}")

    return sections
